@@ -1,12 +1,40 @@
+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_FILE = path.join(process.cwd(), ".session-cache.json");
+let store = new Map<string, Entry>();
+
+const loadFromDisk = (): void => {
+  try {
+    if (fs.existsSync(CACHE_FILE)) {
+      const data = fs.readFileSync(CACHE_FILE, "utf-8");
+      const entries = JSON.parse(data) as Record<string, Entry>;
+      store = new Map(Object.entries(entries));
+    }
+  } catch (error) {
+    console.error("Failed to load cache from disk:", error);
+  }
+};
+
+const saveToDisk = (): void => {
+  try {
+    const entries = Object.fromEntries(store);
+    fs.writeFileSync(CACHE_FILE, JSON.stringify(entries));
+  } catch (error) {
+    console.error("Failed to save cache to disk:", error);
+  }
+};
+
+loadFromDisk();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveToDisk();
 };

